CREATE TABLE IF NOT EXISTS wai_organizations (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wai_users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wai_memberships (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid NOT NULL REFERENCES wai_users(id), role text NOT NULL CHECK(role IN ('admin','doctor','viewer')), external_subject text, UNIQUE(tenant_id,user_id), UNIQUE(tenant_id,external_subject));
CREATE TABLE IF NOT EXISTS wai_auth_sessions (token_hash text PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,user_id) REFERENCES wai_memberships(tenant_id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wai_specialties (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), name text NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_specialty_packs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), specialty_id uuid, name text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,specialty_id) REFERENCES wai_specialties(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_templates (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), name text NOT NULL, specialty text NOT NULL, current_version uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_template_versions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, template_id uuid NOT NULL, version integer NOT NULL, document jsonb NOT NULL, published_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(template_id,version), FOREIGN KEY(tenant_id,template_id) REFERENCES wai_templates(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_template_fields (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, version_id uuid NOT NULL, field_key text NOT NULL, definition jsonb NOT NULL, UNIQUE(version_id,field_key), FOREIGN KEY(tenant_id,version_id) REFERENCES wai_template_versions(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_template_rules (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, version_id uuid NOT NULL, definition jsonb NOT NULL, FOREIGN KEY(tenant_id,version_id) REFERENCES wai_template_versions(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_sessions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid NOT NULL, template_version uuid NOT NULL, status text NOT NULL DEFAULT 'recording' CHECK(status IN ('recording','review','approved')), revision integer NOT NULL DEFAULT 0, context bytea NOT NULL, result bytea, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES wai_memberships(tenant_id,user_id), FOREIGN KEY(tenant_id,template_version) REFERENCES wai_template_versions(tenant_id,id));
CREATE INDEX IF NOT EXISTS wai_sessions_owner ON wai_sessions(tenant_id,user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS wai_session_chunks (id uuid NOT NULL, tenant_id uuid NOT NULL, session_id uuid NOT NULL, sequence integer NOT NULL CHECK(sequence>=1), revision integer NOT NULL CHECK(revision>=1), is_final boolean NOT NULL, timestamp timestamptz NOT NULL, text bytea NOT NULL, digest text NOT NULL, PRIMARY KEY(session_id,id), UNIQUE(session_id,sequence), FOREIGN KEY(tenant_id,session_id) REFERENCES wai_sessions(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wai_extracted_facts (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, session_id uuid NOT NULL, revision integer NOT NULL, payload bytea NOT NULL, FOREIGN KEY(tenant_id,session_id) REFERENCES wai_sessions(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wai_session_revisions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, session_id uuid NOT NULL, revision integer NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,revision), FOREIGN KEY(tenant_id,session_id) REFERENCES wai_sessions(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wai_clinical_results (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, session_id uuid NOT NULL, revision integer NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(session_id,revision), FOREIGN KEY(tenant_id,session_id) REFERENCES wai_sessions(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wai_approvals (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, session_id uuid NOT NULL, user_id uuid NOT NULL, revision integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,revision), FOREIGN KEY(tenant_id,session_id) REFERENCES wai_sessions(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,user_id) REFERENCES wai_memberships(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS wai_audit_events (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid REFERENCES wai_users(id), action text NOT NULL, entity_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS wai_audit_tenant_date ON wai_audit_events(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS wai_usage_records (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid REFERENCES wai_users(id), provider text NOT NULL, model text NOT NULL, input_tokens integer NOT NULL, output_tokens integer NOT NULL, cost_usd numeric(14,8) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS wai_usage_tenant_date ON wai_usage_records(tenant_id,created_at);
CREATE TABLE IF NOT EXISTS wai_pairing_tokens (token_hash text PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, session_id uuid NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,session_id) REFERENCES wai_sessions(tenant_id,id) ON DELETE CASCADE);
